<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Database.php';require_once __DIR__.'/../core/Response.php';Auth::requirePermission('work_planner.templates');$pageTitle='قالب‌های پلنر کاری';
$types=['daily'=>'روزانه','weekly'=>'هفتگی','monthly'=>'ماهانه','periodic'=>'دوره‌ای','kpi_related'=>'مرتبط با KPI','report'=>'گزارش','meeting'=>'جلسه','follow_up'=>'پیگیری','field_visit'=>'ویزیت میدانی','admin_task'=>'اداری','custom'=>'سفارشی'];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('درخواست نامعتبر است.','danger');redirect('/admin/work-planner-templates.php');}try{$id=(int)($_POST['id']??0);$title=trim((string)($_POST['title']??''));$roleId=(int)($_POST['organizational_role_id']??0)?:null;$unitId=(int)($_POST['unit_id']??0)?:null;if($title==='')throw new InvalidArgumentException('عنوان قالب الزامی است.');$duplicate=Database::fetch('SELECT id FROM work_planner_templates WHERE title=? AND organizational_role_id <=> ? AND unit_id <=> ? AND id<>? LIMIT 1',[$title,$roleId,$unitId,$id]);if($duplicate)throw new InvalidArgumentException('قالب مشابه برای این نقش و واحد قبلاً ثبت شده است.');$role=$roleId?Database::fetch('SELECT code FROM org_roles WHERE id=?',[$roleId]):null;$unit=$unitId?Database::fetch('SELECT code FROM org_units WHERE id=?',[$unitId]):null;$data=[$title,trim((string)($_POST['description']??'')),$role['code']??null,$unit['code']??null,$unitId,$roleId,array_key_exists($_POST['task_type']??'',$types)?$_POST['task_type']:'custom',in_array($_POST['priority']??'',['low','normal','high','urgent'],true)?$_POST['priority']:'normal',max(0,(int)($_POST['default_due_offset_days']??0)),in_array($_POST['recurrence_type']??'',['none','daily','weekly','monthly','custom'],true)?$_POST['recurrence_type']:'none',trim((string)($_POST['recurrence_rule']??'')),isset($_POST['is_required'])?1:0,isset($_POST['is_visible_on_dashboard'])?1:0,isset($_POST['is_active'])?1:0,max(0,(int)($_POST['sort_order']??0))];if($id)Database::execute('UPDATE work_planner_templates SET title=?,description=?,role_key=?,department_key=?,unit_id=?,organizational_role_id=?,task_type=?,priority=?,default_due_offset_days=?,recurrence_type=?,recurrence_rule=?,is_required=?,is_visible_on_dashboard=?,is_active=?,sort_order=?,updated_at=NOW() WHERE id=?',[...$data,$id]);else Database::execute('INSERT INTO work_planner_templates(title,description,role_key,department_key,unit_id,organizational_role_id,task_type,priority,default_status,default_due_offset_days,recurrence_type,recurrence_rule,is_required,is_visible_on_dashboard,is_active,sort_order,created_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?, ?,"todo",?,?,?,?,?,?,?,?,NOW(),NOW())',[...$data,(int)Auth::user()['id']]);flash('قالب وظیفه ذخیره شد.');}catch(InvalidArgumentException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Work planner template: '.$e->getMessage());flash('ذخیره قالب انجام نشد. لطفاً دوباره تلاش کنید.','danger');}redirect('/admin/work-planner-templates.php');}
$edit=isset($_GET['edit'])?Database::fetch('SELECT * FROM work_planner_templates WHERE id=?',[(int)$_GET['edit']]):null;$templates=Database::fetchAll('SELECT t.*,u.title unit_title,r.title role_title FROM work_planner_templates t LEFT JOIN org_units u ON u.id=t.unit_id LEFT JOIN org_roles r ON r.id=t.organizational_role_id ORDER BY t.sort_order,t.id');$units=Database::fetchAll('SELECT id,title,active FROM org_units ORDER BY sort_order,title');$roles=Database::fetchAll('SELECT id,title,active FROM org_roles ORDER BY sort_order,title');require __DIR__.'/../views/partials/admin-header.php';?>
<section class="card admin-form"><h2><?=$edit?'ویرایش قالب':'قالب وظیفه جدید'?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="grid grid-3"><label class="form-field"><span>عنوان</span><input name="title" value="<?=e($edit['title']??'')?>" required></label><label class="form-field"><span>نقش</span><select name="organizational_role_id"><option value="">همه نقش‌ها</option><?php foreach($roles as $r):if(!$r['active']&&(int)($edit['organizational_role_id']??0)!==(int)$r['id'])continue?><option value="<?=e((string)$r['id'])?>" <?=(int)($edit['organizational_role_id']??0)===(int)$r['id']?'selected':''?>><?=e($r['title'])?></option><?php endforeach?></select></label><label class="form-field"><span>واحد</span><select name="unit_id"><option value="">همه واحدها</option><?php foreach($units as $u):if(!$u['active']&&(int)($edit['unit_id']??0)!==(int)$u['id'])continue?><option value="<?=e((string)$u['id'])?>" <?=(int)($edit['unit_id']??0)===(int)$u['id']?'selected':''?>><?=e($u['title'])?></option><?php endforeach?></select></label><label class="form-field"><span>نوع وظیفه</span><select name="task_type"><?php foreach($types as $v=>$l):?><option value="<?=e($v)?>" <?=($edit['task_type']??'custom')===$v?'selected':''?>><?=e($l)?></option><?php endforeach?></select></label><label class="form-field"><span>اولویت</span><select name="priority"><?php foreach(['low'=>'کم','normal'=>'عادی','high'=>'بالا','urgent'=>'فوری'] as $v=>$l):?><option value="<?=e($v)?>" <?=($edit['priority']??'normal')===$v?'selected':''?>><?=e($l)?></option><?php endforeach?></select></label><label class="form-field"><span>تکرار</span><select name="recurrence_type"><?php foreach(['none'=>'بدون تکرار','daily'=>'روزانه','weekly'=>'هفتگی','monthly'=>'ماهانه','custom'=>'سفارشی'] as $v=>$l):?><option value="<?=e($v)?>" <?=($edit['recurrence_type']??'none')===$v?'selected':''?>><?=e($l)?></option><?php endforeach?></select></label><label class="form-field"><span>قاعده سفارشی</span><input name="recurrence_rule" value="<?=e($edit['recurrence_rule']??'')?>" placeholder="شماره روزهای هفته: 1,3,5"></label><label class="form-field"><span>فاصله مهلت (روز)</span><input type="number" min="0" name="default_due_offset_days" value="<?=e($edit['default_due_offset_days']??0)?>"></label><label class="form-field"><span>ترتیب</span><input type="number" min="0" name="sort_order" value="<?=e($edit['sort_order']??0)?>"></label><label class="checkbox-item"><input type="checkbox" name="is_required" <?=(int)($edit['is_required']??0)?'checked':''?>> اجباری و قفل‌شده</label><label class="checkbox-item"><input type="checkbox" name="is_visible_on_dashboard" <?=!isset($edit['is_visible_on_dashboard'])||(int)$edit['is_visible_on_dashboard']?'checked':''?>> نمایش در داشبورد</label><label class="checkbox-item"><input type="checkbox" name="is_active" <?=!isset($edit['is_active'])||(int)$edit['is_active']?'checked':''?>> فعال</label><label class="form-field grid-span-2"><span>شرح</span><textarea name="description"><?=e($edit['description']??'')?></textarea></label></div><div class="form-actions"><button class="btn btn-primary">ذخیره قالب</button><?php if($edit):?><a class="btn" href="/admin/work-planner-templates.php">انصراف</a><?php endif?></div></form></section>
<section class="card"><div class="table-wrap"><table><thead><tr><th>قالب</th><th>نقش / واحد</th><th>نوع / تکرار</th><th>اولویت</th><th>وضعیت</th><th></th></tr></thead><tbody><?php foreach($templates as $t):?><tr><td><?=e($t['title'])?><small><?=e($t['description']?:'-')?></small></td><td><?=e(($t['role_title']?:'همه نقش‌ها').' / '.($t['unit_title']?:'همه واحدها'))?></td><td><?=e(($types[$t['task_type']]??$t['task_type']).' / '.$t['recurrence_type'])?></td><td><?=e($t['priority'])?></td><td><?=((int)$t['is_active']?'فعال':'غیرفعال')?><?=((int)$t['is_required']?' / اجباری':'')?></td><td><a class="btn btn-small" href="?edit=<?=e((string)$t['id'])?>">ویرایش</a></td></tr><?php endforeach?></tbody></table></div></section>
